package O1;
import android.app.*;
import java.io.*;
import java.lang.reflect.*;
import java.nio.file.*;
import java.security.*;
import java.util.*;

/** Admit the real catalog through the original P5 classes, using only isolated files. */
public class ActualCatalog206Test {
 static int checks;
 static void check(boolean ok,String label){if(!ok)throw new AssertionError(label);checks++;}
 static String hash(byte[] bytes)throws Exception{StringBuilder s=new StringBuilder();for(byte b:MessageDigest.getInstance("SHA-256").digest(bytes))s.append(String.format("%02x",b&255));return s.toString();}
 static List<String> lines(Path file)throws Exception{return Files.readAllLines(file,java.nio.charset.StandardCharsets.UTF_8);}
 static Map<String,String[]> catalog(Path file)throws Exception{
  List<String> all=lines(file);check("ffbe-content-v1".equals(all.get(0)),"actual pinned catalog header");Map<String,String[]> rows=new LinkedHashMap<>();
  for(String line:all.subList(1,all.size())){String[] fields=line.split("\t",-1);check(fields.length==8,"actual eight-field catalog row");check(rows.put(fields[0],fields)==null,"actual catalog path unique");}
  return rows;
 }
 @SuppressWarnings("unchecked") static Map<String,ExtraContent.Entry> loaded()throws Exception{Field f=ExtraContent.class.getDeclaredField("entries");f.setAccessible(true);return (Map<String,ExtraContent.Entry>)f.get(null);}
 static void seed(Path root,Map<String,ExtraContent.Entry> rows,Path file)throws Exception{
  for(String line:lines(file)){String[] p=line.split("\t",-1);if(p.length==1&&p[0].isEmpty())continue;ExtraContent.Entry e=rows.get(p[0]);check(e!=null,"seed is an actual catalog entry");byte[] bytes=Files.readAllBytes(Paths.get(p[1]));check(bytes.length==e.size&&hash(bytes).equals(e.hash),"seed source bytes independently match actual entry");Path destination=ExtraContent.target(e).toPath();check(destination.equals(root.resolve(p[2])),"original target matches independently retained P5/203 cache path");Files.createDirectories(destination.getParent());Files.write(destination,bytes);}
 }
 public static void main(String[] args)throws Exception{
  Path payload=Paths.get(args[0]),original=Paths.get(args[1]),fixtures=Paths.get(args[2]),requirements=Paths.get(args[3]);Path root=Files.createTempDirectory(fixtures,"actual206-");Path assets=root.resolve("assets"),files=root.resolve("files");Files.createDirectories(assets.resolve("side_stories"));Files.createDirectories(files);
  Files.copy(payload.resolve("content_delivery.tsv"),assets.resolve("content_delivery.tsv"));Files.copy(original.resolve("base_delivery.tsv"),assets.resolve("base_delivery.tsv"));Files.copy(payload.resolve("side_stories/manifest.tsv"),assets.resolve("side_stories/manifest.tsv"));
  ActivityThread.app=new Application(files.toFile(),assets.toFile());
  Map<String,String[]> actual=catalog(payload.resolve("content_delivery.tsv")),prior=catalog(original.resolve("content_delivery.tsv"));check(prior.size()==1898,"exact v205 inherited descriptor count");Set<String> approved=new HashSet<>(lines(requirements.resolve("approved-paths.txt")));Set<String> changed=new LinkedHashSet<>();List<String> originalOrder=new ArrayList<>(prior.keySet()),actualOrder=new ArrayList<>(actual.keySet());check(actualOrder.equals(originalOrder),"all v205 catalog paths and row order preserved");
  for(Map.Entry<String,String[]> row:prior.entrySet()){String[] now=actual.get(row.getKey());check(now!=null,"every original P5 descriptor retained");if(!Arrays.equals(now,row.getValue())){check(approved.contains(row.getKey()),"only approved missing-event revision can alter original descriptor");changed.add(row.getKey());}}
  Set<String> added=new LinkedHashSet<>(actual.keySet());added.removeAll(prior.keySet());check(added.isEmpty(),"event cleanup adds no new logical download paths");
  Map<String,ExtraContent.Entry> admitted=new LinkedHashMap<>();for(Map.Entry<String,String[]> row:actual.entrySet()){ExtraContent.Entry e=new ExtraContent.Entry(row.getValue());admitted.put(e.path,e);check(e.path.equals(row.getKey()),"actual original Entry constructor admits exact path");Path target=ExtraContent.target(e).toPath();check(target.normalize().startsWith(files)&&!target.toString().contains(".."),"actual destination stays in isolated owned cache");}
  ExtraContent.load();Map<String,ExtraContent.Entry> loaded=loaded();check(loaded.size()==actual.size()&&loaded.keySet().equals(actual.keySet()),"actual original load admits complete catalog");
  Map<String,String[]> side=new LinkedHashMap<>();for(String line:lines(payload.resolve("side_stories/manifest.tsv"))){String[] p=line.split("\t",-1);check(p.length==3||p.length==4,"actual side manifest field count");check(p[0].matches("(?:[A-Za-z0-9_.-]+|r2_scene_(jp|gl)/[a-f0-9]{16}/[A-Za-z0-9_.-]+[.]cpk)")&&!p[0].contains(".."),"actual side manifest path narrowly safe");check(p[1].matches("[a-f0-9]{64}"),"actual side manifest hash");check(side.put(p[0],p)==null,"actual side manifest names unique");ExtraContent.Entry entry=loaded.get("side_stories/"+p[0]);check(entry!=null&&entry.hash.equals(p[1]),"every actual side manifest payload resolves to exact catalog hash");for(String accepted:p[2].split(","))if(!accepted.isEmpty())check(accepted.matches("[a-f0-9]{64}"),"actual accepted-original source hash");}
  for(String[] row:side.values())if(row.length==4&&!row[3].isEmpty())for(String variant:row[3].split(",")){String[] pair=variant.split("=",-1);check(pair.length==2&&pair[0].matches("[a-f0-9]{64}")&&side.containsKey(pair[1]),"every actual source variant resolves to declared side entry");}
  Method loadSide=SideStoryTables.class.getDeclaredMethod("load",Object.class);loadSide.setAccessible(true);loadSide.invoke(null,ActivityThread.app);Field sf=SideStoryTables.class.getDeclaredField("entries");sf.setAccessible(true);check(((Map<?,?>)sf.get(null)).size()==side.size(),"minimally extended original SideStoryTables loads every actual row");
  seed(files,loaded,requirements.resolve("cached-old.tsv"));seed(files,loaded,requirements.resolve("cached-experimental.tsv"));
  String[] partialInfo=lines(requirements.resolve("partial.tsv")).get(0).split("\t",-1);ExtraContent.Entry partialEntry=loaded.get(partialInfo[0]);check(partialEntry!=null,"saved partial belongs to actual new/revised event entry");byte[] partialBytes=Files.readAllBytes(Paths.get(partialInfo[1]));Path partial=files.resolve("content_delivery/"+partialEntry.hash+".part");Files.createDirectories(partial.getParent());Files.write(partial,partialBytes);check(partialBytes.length>0&&partialBytes.length<partialEntry.wireSize,"genuine saved compressed partial shorter than actual range");
  byte[] save="isolated saved progress".getBytes("UTF-8");Path saveFile=files.resolve("profile.save");Files.write(saveFile,save);Map<String,ExtraContent.Entry> pending=new LinkedHashMap<>();for(ExtraContent.Entry e:ExtraContent.missing())check(pending.put(e.hash,e)==null,"existing extra queue deduplicates exact hash");
  Set<String> seeded=new HashSet<>();for(String name:new String[]{"cached-old.tsv","cached-experimental.tsv"})for(String line:lines(requirements.resolve(name))){String[] p=line.split("\t",-1);seeded.add(loaded.get(p[0]).hash);check(!pending.containsKey(loaded.get(p[0]).hash),"verified inherited/experimental object omitted from missing queue");}
  Set<String> expectedHashes=new HashSet<>();for(ExtraContent.Entry e:loaded.values())if(!seeded.contains(e.hash))expectedHashes.add(e.hash);check(pending.keySet().equals(expectedHashes),"existing queue contains exactly every uncached actual hash");for(String path:added)check(seeded.contains(loaded.get(path).hash)||pending.containsKey(loaded.get(path).hash),"every actual missing new event asset belongs to existing queue");for(String path:changed)check(seeded.contains(loaded.get(path).hash)||pending.containsKey(loaded.get(path).hash),"every revised event asset belongs to existing queue");check(pending.get(partialEntry.hash).transferred==partialBytes.length,"saved actual partial byte count retained for existing resume engine");
  List<List<ExtraContent.Entry>> batches=ExtraContent.batches(new ArrayList<>(pending.values()));Set<String> batched=new HashSet<>();for(List<ExtraContent.Entry> batch:batches)for(ExtraContent.Entry e:batch)check(batched.add(e.hash),"original batching includes each actual missing hash once");check(batched.equals(expectedHashes),"actual original batch set complete");
  ContentDownloader.checkAssets();check(ContentDownloader.getNeedsDownload(),"existing native callback reports new downloads required");check(!ContentDownloader.getIsCheckingState()&&!ContentDownloader.getIsDownloading(),"catalog admission preserves native checking/download state");check(ContentDownloader.getTotalCount()==pending.size()+CdnDownloader.getTotalCount(),"unchanged native callback combines actual extra and base missing counts");long total=CdnDownloader.getTotalSize();for(ExtraContent.Entry e:pending.values())total+=e.wireSize;check(ContentDownloader.getTotalSize()==total,"unchanged native screen reports exact actual wire byte total");
  check(Arrays.equals(partialBytes,Files.readAllBytes(partial))&&Arrays.equals(save,Files.readAllBytes(saveFile)),"catalog/native queue admission preserves partial and isolated save bytes");
  System.out.println("PASSED "+checks+" actual206 catalog/native queue checks; rows="+actual.size()+" side="+side.size()+" added="+added.size()+" changed="+changed.size()+" extra-missing="+pending.size()+" base-missing="+CdnDownloader.getTotalCount());
 }
}
